/// <reference types="cypress" />

/**
 * Login to SauceDemo using credentials from environment variables
 * @param {string} username - Username (defaults to cy.env('username'))
 * @param {string} password - Password (defaults to cy.env('password'))
 */
Cypress.Commands.add('login', (username, password) => {
  // Fetch credentials from cy.env() if not provided (Cypress 16+ compatible)
  // cy.env() now requires an array of strings: cy.env(['key1', 'key2'])
  const getCredentials = () => {
    if (username && password) {
      return cy.wrap({ username, password });
    }
    return cy.env(['username', 'password']).then((env) =>
      cy.wrap({ username: env.username, password: env.password })
    );
  };

  getCredentials().then((creds) => {
    const { username: user, password: pass } = creds;
    cy.log('🔐 [LOGIN] Attempting login with user:', user);
    // Visit with longer timeout for network issues
    cy.visit('/', { timeout: 30000 });
    cy.log('🌐 [LOGIN] Visited login page');
    // Wait for login form to be visible
    cy.get('[data-test="username"]', { timeout: 10000 }).should('be.visible');
    cy.log('📝 [LOGIN] Username field visible, typing credentials');
    cy.get('[data-test="username"]').clear().type(user);
    cy.get('[data-test="password"]').clear().type(pass);
    cy.log('🔘 [LOGIN] Clicking login button');
    cy.get('[data-test="login-button"]').click();
    // Verify successful login by checking inventory page
    cy.url({ timeout: 15000 }).should('include', '/inventory.html');
    cy.log('✅ [LOGIN] Login successful - on inventory page');
  });
});

/**
 * Add a product to cart by its data-test attribute
 * @param {string} productName - Product name to add to cart
 */
Cypress.Commands.add('addToCart', (productName) => {
  cy.log('🛒 [ADD_TO_CART] Adding product:', productName);
  // Find the product by name and click its add to cart button
  cy.contains('.inventory_item_name', productName)
    .parents('.inventory_item')
    .find('[data-test^="add-to-cart"]')
    .click();
  cy.log('✅ [ADD_TO_CART] Added:', productName);
});

/**
 * Add ALL products to cart
 */
Cypress.Commands.add('addAllItemsToCart', () => {
  cy.log('🛒 [ADD_ALL_ITEMS] Adding all products to cart');
  // Get all add-to-cart buttons and click each one
  cy.get('[data-test^="add-to-cart"]').each(($btn, index) => {
    cy.log(`🛒 [ADD_ALL_ITEMS] Clicking item ${index + 1}`);
    cy.wrap($btn).click();
  });
  cy.log('✅ [ADD_ALL_ITEMS] All items added to cart');
});

/**
 * Remove a product from cart by its data-test attribute
 * @param {string} productName - Product name to remove from cart
 */
Cypress.Commands.add('removeFromCart', (productName) => {
  cy.log('🗑️ [REMOVE_FROM_CART] Removing product:', productName);
  cy.contains('.inventory_item_name', productName)
    .parents('.inventory_item')
    .find('[data-test^="remove"]')
    .click();
  cy.log('✅ [REMOVE_FROM_CART] Removed:', productName);
});

/**
 * Navigate to cart page
 */
Cypress.Commands.add('goToCart', () => {
  cy.log('🛍️ [GO_TO_CART] Navigating to cart page');
  cy.get('[data-test="shopping-cart-link"]').click();
  cy.url().should('include', '/cart.html');
  cy.log('✅ [GO_TO_CART] On cart page');
});

/**
 * Complete checkout process
 * @param {object} info - Checkout information (firstName, lastName, postalCode)
 */
Cypress.Commands.add('checkout', (info = { firstName: 'John', lastName: 'Doe', postalCode: '12345' }) => {
  cy.log('💳 [CHECKOUT] Starting checkout process');
  cy.get('[data-test="checkout"]').click();
  cy.url().should('include', '/checkout-step-one.html');
  cy.log('📝 [CHECKOUT] Filling checkout info');
  cy.get('[data-test="firstName"]').clear().type(info.firstName);
  cy.get('[data-test="lastName"]').clear().type(info.lastName);
  cy.get('[data-test="postalCode"]').clear().type(info.postalCode);
  cy.log('➡️ [CHECKOUT] Continuing to overview');
  cy.get('[data-test="continue"]').click();
  cy.url().should('include', '/checkout-step-two.html');
  cy.log('✅ [CHECKOUT] On overview page');

  // Verify overview and finish
  cy.get('[data-test="finish"]').click();
  cy.url().should('include', '/checkout-complete.html');
  cy.contains('Thank you for your order!').should('be.visible');
  cy.log('🎉 [CHECKOUT] Order completed successfully');
});

/**
 * Logout from SauceDemo
 */
Cypress.Commands.add('logout', () => {
  cy.log('🚪 [LOGOUT] Opening menu');
  // Use force: true because the  inside the button is covered by the button itself
  cy.get('[data-test="open-menu"]').click({ force: true });
  cy.log('🚪 [LOGOUT] Clicking logout link');
  // Use force: true because sidebar link may not pass visibility check immediately
  cy.get('[data-test="logout-sidebar-link"]').click({ force: true });
  cy.url().should('eq', Cypress.config().baseUrl + '/');
  cy.log('✅ [LOGOUT] Logged out successfully');
});